// ───────────────────────── генераторы тренажёра (системы органов, путь еды, витамины, числа о теле)
(function () {
  const S = window.SUBJECTS.body, U = id => S.units.find(u => u.id === id);
  const rnd = n => Math.floor(Math.random() * n), pick = a => a[rnd(a.length)], shuf = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = rnd(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const one = (q, right, wrong, why) => { const a = shuf([right, ...wrong]); return { type: 'one', q, a, c: a.indexOf(right), why }; };
  const tf = (q, c, why) => ({ type: 'tf', q, c, why });
  const nOpt = lv => (lv === 1 ? 3 : 4);
  const sub = (arr, k) => shuf(arr).slice(0, k);
  const ordered = (arr, k) => shuf(arr.map((_, i) => i)).slice(0, k).sort((x, y) => x - y).map(i => arr[i]); // k элементов, порядок сохранён
  const low = s => s.charAt(0).toLowerCase() + s.slice(1);
  const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
  /* sort: по одному элементу из каждой группы, остальное — случайно из общего пула */
  const sortQ = (q, groups, lists, n, why) => {
    const base = lists.map((l, gi) => [pick(l), gi]);
    const rest = shuf(lists.flatMap((l, gi) => l.map(t => [t, gi])).filter(p => !base.some(b => b[0] === p[0])));
    return { type: 'sort', q, groups, items: shuf(base.concat(rest.slice(0, Math.max(0, n - base.length)))), why };
  };

  // ═════════ 1. Клетки → системы органов (какой орган к какой системе, пути по системам)
  const SYS = [
    { n: 'Опорно-двигательная', g: 'опорно-двигательной', v: 'опорно-двигательную', o: ['Кости', 'Скелетные мышцы', 'Суставы', 'Позвоночник', 'Сухожилия', 'Череп'], f: 'держит тело и двигает его' },
    { n: 'Кровеносная', g: 'кровеносной', v: 'кровеносную', o: ['Сердце', 'Артерии', 'Вены', 'Капилляры'], f: 'развозит кислород и питание по всему телу' },
    { n: 'Дыхательная', g: 'дыхательной', v: 'дыхательную', o: ['Лёгкие', 'Трахея', 'Бронхи', 'Гортань', 'Альвеолы'], f: 'берёт из воздуха кислород и выдыхает углекислый газ' },
    { n: 'Пищеварительная', g: 'пищеварительной', v: 'пищеварительную', o: ['Желудок', 'Пищевод', 'Тонкая кишка', 'Толстая кишка', 'Печень', 'Поджелудочная железа'], f: 'разбирает еду на полезные частички' },
    { n: 'Нервная', g: 'нервной', v: 'нервную', o: ['Головной мозг', 'Спинной мозг', 'Нервы'], f: 'управляет телом и передаёт сигналы' },
    { n: 'Выделительная', g: 'выделительной', v: 'выделительную', o: ['Почки', 'Мочевой пузырь', 'Мочеточники'], f: 'выводит из тела лишнюю воду и отходы' }
  ];
  const ORG = SYS.flatMap(s => s.o.map(o => ({ o, s })));
  const sysWhy = s => s.n + ' система (' + s.o.map(low).join(', ') + ') ' + s.f + '.';
  const PATHS = [
    { q: 'Проследи путь воздуха при вдохе.', it: ['Нос', 'Гортань', 'Трахея', 'Бронхи', 'Альвеолы в лёгких'], why: 'Нос → гортань → трахея → бронхи → альвеолы.' },
    { q: 'Проследи путь крови по большому кругу.', it: ['Сердце', 'Артерии', 'Капилляры в органах', 'Вены', 'Обратно в сердце'], why: 'От сердца по артериям, через капилляры, по венам — обратно к сердцу.' },
    { q: 'Проследи малый круг кровообращения.', it: ['Сердце', 'Сосуды к лёгким', 'Кровь берёт кислород в лёгких', 'Обратно в сердце'], why: 'Малый круг: сердце → лёгкие → сердце.' },
    { q: 'Проследи путь в выделительной системе.', it: ['Почки фильтруют кровь', 'Мочеточники', 'Мочевой пузырь', 'Наружу'], why: 'Почки → мочеточники → мочевой пузырь.' },
    { q: 'Расставь от самого маленького к самому большому.', it: ['Клетка', 'Ткань', 'Орган', 'Система органов', 'Организм'], why: 'Клетка → ткань → орган → система → организм.' },
    { q: 'Собери «матрёшку» сердца: от маленького к большому.', it: ['Мышечная клетка', 'Мышечная ткань', 'Сердце', 'Кровеносная система', 'Организм'], why: 'Клетки → ткань → орган → система → организм.' },
    { q: 'Собери «матрёшку» мозга: от маленького к большому.', it: ['Нейрон', 'Нервная ткань', 'Головной мозг', 'Нервная система', 'Организм'], why: 'Нейрон → нервная ткань → мозг → нервная система → организм.' },
    { q: 'Рефлекс «Горячо!»: расставь по порядку.', it: ['Кожа чувствует жар', 'Нерв несёт сигнал в спинной мозг', 'Спинной мозг командует мышцам', 'Рука отдёргивается'], why: 'Рефлекс проходит через спинной мозг — быстрее, чем через голову.' }
  ];
  U('cells').gen = lv => {
    const t = rnd(7);
    if (t === 0) { const x = pick(ORG); return one('«' + x.o + '» — часть какой системы органов?', x.s.n, sub(SYS.filter(s => s !== x.s), nOpt(lv) - 1).map(s => s.n), sysWhy(x.s)); }
    if (t === 1) { const s = pick(SYS); return one('Что входит в ' + s.v + ' систему?', pick(s.o), sub(ORG.filter(x => x.s !== s), nOpt(lv) - 1).map(x => x.o), sysWhy(s)); }
    if (t === 2) {
      const x = pick(ORG), truth = Math.random() < 0.5, s = truth ? x.s : pick(SYS.filter(y => y !== x.s));
      return tf('«' + x.o + '» — часть ' + s.g + ' системы.', truth, truth ? 'Верно! ' + sysWhy(x.s) : 'Нет: «' + x.o + '» относится к ' + x.s.g + ' системе. ' + sysWhy(x.s));
    }
    if (t === 3) { const gs = sub(SYS, lv === 3 ? 3 : 2); return sortQ('Разложи органы по системам.', gs.map(s => s.n), gs.map(s => s.o), lv === 1 ? 5 : lv === 2 ? 6 : 7, gs.map(sysWhy).join(' ')); }
    if (t === 4) { const s = pick(SYS); return one('Какая система органов ' + s.f + '?', s.n, sub(SYS.filter(y => y !== s), nOpt(lv) - 1).map(y => y.n), sysWhy(s)); }
    if (t === 5) { const p = pick(PATHS); return { type: 'order', q: p.q, items: ordered(p.it, Math.min(p.it.length, lv === 1 ? 3 : lv === 2 ? 4 : 5)), why: p.why }; }
    const s = pick(SYS), k = lv === 1 ? 4 : lv === 2 ? 5 : 6, nIn = 1 + rnd(Math.min(s.o.length, k - 1));
    const list = shuf(sub(s.o, nIn).concat(sub(ORG.filter(x => x.s !== s).map(x => x.o), k - nIn)));
    return { type: 'input', q: 'Сколько из этих органов входят в ' + s.v + ' систему: ' + list.map(low).join(', ') + '?', c: nIn, why: 'Из этого списка в ' + s.g + ' системе: ' + list.filter(o => s.o.includes(o)).map(low).join(', ') + '.' };
  };

  // ═════════ 2. Пищеварение: путь еды, станции, тарелка
  const ST = [
    { n: 'Рот', f: ['Зубы перемалывают еду', 'Слюна смачивает кусочек', 'Язык перемешивает еду', 'Пищеварение только начинается'] },
    { n: 'Пищевод', f: ['Мышцы проталкивают еду волной', 'Трубка от горла к желудку', 'Глотать можно даже вниз головой'] },
    { n: 'Желудок', f: ['Еда перемешивается с кислым соком', 'Растягивается, как мешок, когда мы много съели', 'Стенки защищены слизью от кислоты'] },
    { n: 'Тонкая кишка', f: ['Почти всё полезное из еды всасывается в кровь', 'Самая длинная часть пути — несколько метров', 'Сюда приходит желчь из печени'] },
    { n: 'Толстая кишка', f: ['Из остатков еды забирается вода', 'Здесь больше всего полезных бактерий', 'Последняя станция пути еды'] },
    { n: 'Печень', f: ['Делает желчь', 'Обезвреживает вредные вещества', 'Самый большой внутренний орган'], help: true },
    { n: 'Поджелудочная железа', f: ['Прячется за желудком и выделяет сок для тонкой кишки'], help: true }
  ];
  const PATH = ST.filter(s => !s.help).map(s => s.n);
  const STEPS = ['Зубы и слюна готовят кусочек', 'Мышцы пищевода проталкивают еду', 'Желудок перемешивает еду с кислым соком', 'В тонкой кишке полезное всасывается в кровь', 'Толстая кишка забирает воду'];
  const PLATE = [['Огурец', 'Помидор', 'Яблоко', 'Морковь', 'Капуста', 'Груша', 'Брокколи', 'Банан'], ['Гречка', 'Рис', 'Макароны', 'Хлеб', 'Овсянка', 'Картошка'], ['Рыба', 'Курица', 'Яйцо', 'Творог', 'Фасоль', 'Говядина']];
  const stWhy = s => s.n + ': ' + s.f.map(low).join('; ') + '.';
  U('digestion').gen = lv => {
    const t = rnd(7);
    if (t === 0) { const s = pick(ST), f = pick(s.f); return one('Где это происходит: «' + f + '»?', s.n, sub(ST.filter(x => x !== s), nOpt(lv) - 1).map(x => x.n), stWhy(s)); }
    if (t === 1) { const s = pick(ST); return one('Какая улика — про орган «' + s.n + '»?', pick(s.f), sub(ST.filter(x => x !== s), nOpt(lv) - 1).map(x => pick(x.f)), stWhy(s)); }
    if (t === 2) {
      const s = pick(ST), truth = Math.random() < 0.5, o = truth ? s : pick(ST.filter(x => x !== s)), f = pick(o.f);
      return tf(s.n + ': ' + low(f) + '.', truth, truth ? 'Верно! ' + stWhy(s) : 'Нет, это про другой орган. ' + stWhy(o));
    }
    if (t === 3) {
      if (Math.random() < 0.5) return { type: 'order', q: 'Проследи путь еды по пищеварительному тракту.', items: ordered(PATH, lv === 1 ? 3 : lv === 2 ? 4 : 5), why: 'Рот → пищевод → желудок → тонкая кишка → толстая кишка.' };
      return { type: 'order', q: 'Что происходит с бутербродом? Расставь по порядку.', items: ordered(STEPS, lv === 1 ? 3 : lv === 2 ? 4 : 5), why: 'Рот → пищевод → желудок → тонкая кишка → толстая кишка.' };
    }
    if (t === 4) { const gs = sub(ST.filter(s => s.f.length >= 3), lv === 3 ? 3 : 2); return sortQ('Разложи улики по органам.', gs.map(s => s.n), gs.map(s => s.f), lv === 1 ? 5 : lv === 2 ? 6 : 7, gs.map(stWhy).join(' ')); }
    if (t === 5) {
      const names = ['Овощи и фрукты', 'Каши, хлеб, картошка', 'Белок'], gi = lv === 1 ? sub([0, 1, 2], 2).sort() : [0, 1, 2];
      return sortQ('Собери тарелку сыщика: что в какую часть?', gi.map(i => names[i]), gi.map(i => PLATE[i]), lv === 1 ? 5 : lv === 2 ? 6 : 7, 'Половина тарелки — овощи и фрукты, четверть — каши, хлеб или картошка, четверть — белок.');
    }
    const v = rnd(3);
    if (v !== 1) { const x = pick(DIG_Q); return one(x[0], x[1], sub(x[2], nOpt(lv) - 1), x[3]); }
    if (v === 1) { const i = 1 + rnd(PATH.length - 1); return { type: 'input', q: 'Еда идёт по станциям: сначала рот… Какой по счёту станцией будет «' + low(PATH[i]) + '»?', c: i + 1, why: PATH.map((p, n) => (n + 1) + ') ' + low(p)).join(', ') + '.' }; }
  };

  /* вопросы-знания о пищеварении: [вопрос, верный, неверные, почему] */
  const DIG_Q = [
    ['Сколько времени еда обычно бывает в желудке?', 'Примерно 2–4 часа', ['Несколько секунд', 'Целую неделю', 'Ровно сутки'], 'В желудке еда перемешивается с желудочным соком и превращается в кашицу — на это уходит несколько часов.'],
    ['Сколько времени может занять весь путь еды?', 'Примерно от одних до трёх суток', ['Около пяти минут', 'Ровно час', 'Около месяца'], 'Еда проходит рот, пищевод, желудок, тонкую и толстую кишку — это долгий путь.'],
    ['Где начинается пищеварение?', 'Во рту', ['В желудке', 'В толстой кишке', 'В печени'], 'Зубы измельчают еду, а слюна начинает её переваривать.'],
    ['Зачем нужна слюна?', 'Смачивает еду и начинает её переваривать', ['Чистит уши', 'Охлаждает тело', 'Помогает видеть'], 'В слюне есть вещества, которые начинают расщеплять, например, хлеб и кашу.'],
    ['Где питательные вещества в основном всасываются в кровь?', 'В тонкой кишке', ['В пищеводе', 'Во рту', 'В желудке'], 'Стенки тонкой кишки покрыты ворсинками — через них полезное попадает в кровь.'],
    ['Что делает толстая кишка?', 'Забирает из остатков еды воду', ['Жуёт еду', 'Делает желчь', 'Перекачивает кровь'], 'В толстой кишке из остатков всасывается вода, а остальное выводится наружу.'],
    ['Зачем еду нужно тщательно пережёвывать?', 'Желудку легче её переварить', ['Чтобы быстрее съесть', 'Чтобы зубы росли', 'Так вкуснее только конфеты'], 'Мелкие кусочки быстрее пропитываются пищеварительными соками.'],
    ['Через сколько примерно минут после начала еды мозг понимает «я сыт»?', 'Примерно через 20 минут', ['Сразу, через секунду', 'Через сутки', 'Через неделю'], 'Сигнал о сытости приходит не сразу — поэтому есть лучше не спеша.'],
    ['Какой орган делает желчь, которая помогает переваривать жир?', 'Печень', ['Сердце', 'Лёгкие', 'Почки'], 'Желчь из печени расщепляет жир на мелкие капельки.'],
    ['Почему нельзя бегать сразу после плотного обеда?', 'Телу нужно время, чтобы спокойно переварить еду', ['Еда выпадет', 'Желудок уснёт', 'Ноги станут тяжёлыми навсегда'], 'После еды кровь приливает к желудку и кишечнику, им нужен покой.'],
    ['Почему перед едой моют руки?', 'Чтобы микробы с рук не попали в живот', ['Чтобы еда была солонее', 'Так быстрее наешься', 'Чтобы руки не мёрзли'], 'Грязные руки — частая причина кишечных болезней.']
  ];

  // ═════════ 3. Витамины и минералы: где найти и зачем нужен
  const NUT = {
    A: { n: 'Витамин A', l: 'витамина A', w: 'помогает видеть в сумерках и бережёт кожу' },
    C: { n: 'Витамин C', l: 'витамина C', w: 'помогает иммунитету и заживлению ранок' },
    D: { n: 'Витамин D', l: 'витамина D', w: 'помогает костям усваивать кальций' },
    B: { n: 'Витамины группы B', l: 'витаминов группы B', w: 'помогают получать из еды энергию и берегут нервы' },
    Ca: { n: 'Кальций', l: 'кальция', w: 'строительный материал для костей и зубов' },
    Fe: { n: 'Железо', l: 'железа', w: 'помогает крови носить кислород' },
    I: { n: 'Йод', l: 'йода', w: 'нужен щитовидной железе, которая помогает расти и развиваться' },
    F: { n: 'Фтор', l: 'фтора', w: 'укрепляет эмаль зубов' }
  };
  /* продукт → [чем он особенно богат (t), чего в нём тоже заметно (m)].
     Верный ответ и «правда» — только по t; неверные варианты и «неправда» — только продукты без t и без m. */
  const FOOD = [
    ['Морковь', 'A'], ['Тыква', 'A'], ['Абрикосы', 'A', 'Fe'], ['Сладкий красный перец', 'C', 'A'], ['Шиповник', 'C', 'A'], ['Чёрная смородина', 'C'], ['Киви', 'C'], ['Апельсин', 'C'], ['Лимон', 'C'], ['Квашеная капуста', 'C'],
    ['Лосось', 'D B', 'I'], ['Сельдь', 'D B', 'I A'], ['Скумбрия', 'D B', 'I'], ['Яичный желток', 'D', 'A B Fe'], ['Гречка', 'B Fe'], ['Овсянка', 'B', 'Fe'], ['Хлеб из цельного зерна', 'B', 'Fe'], ['Фасоль', 'B Fe'],
    ['Творог', 'Ca', 'B'], ['Сыр', 'Ca', 'A B'], ['Молоко', 'Ca', 'B D'], ['Кефир', 'Ca', 'B'], ['Говядина', 'Fe B'], ['Печень', 'Fe A B'], ['Морская капуста', 'I'], ['Йодированная соль', 'I']
  ].map(([f, t, m]) => ({ f, t: t.split(' '), m: m ? m.split(' ') : [] }));
  const SRC_KEYS = ['A', 'C', 'D', 'B', 'Ca', 'Fe', 'I'];
  const has = (fd, k) => fd.t.includes(k), none = (fd, k) => !fd.t.includes(k) && !fd.m.includes(k);
  const fWhy = fd => fd.f + ' — источник: ' + fd.t.map(k => low(NUT[k].n)).join(', ') + '.';
  const nWhy = k => NUT[k].n + ' ' + NUT[k].w + '. Где найти: ' + FOOD.filter(fd => has(fd, k)).map(fd => low(fd.f)).join(', ') + '.';
  const CHAINS = [
    { q: 'Как витамин D помогает костям? Расставь по порядку.', it: ['Солнце светит на кожу', 'Кожа делает витамин D', 'Витамин D помогает усвоить кальций', 'Кальций укрепляет кости'], why: 'Солнце → витамин D → кальций → крепкие кости.' },
    { q: 'Как морковка помогает глазам? Расставь по порядку.', it: ['Едим морковь со сметаной', 'Жир помогает усвоить полезное вещество', 'Тело делает из него витамин A', 'Глаза лучше видят в сумерках'], why: 'Витамин A растворяется в жире — поэтому морковь едят со сметаной или маслом.' },
    { q: 'Как железо помогает дышать? Расставь по порядку.', it: ['Едим гречку, мясо, фасоль', 'Железо попадает в кровь', 'Железо входит в гемоглобин', 'Эритроциты носят кислород'], why: 'Железо — часть гемоглобина, который переносит кислород.' },
    { q: 'Как витамин C помогает ранке? Расставь по порядку.', it: ['Едим шиповник, смородину, перец', 'Витамин C попадает в кровь', 'Иммунитет и кожа получают помощника', 'Ранка заживает быстрее'], why: 'Витамин C помогает иммунитету и заживлению.' }
  ];
  U('vitamins').gen = lv => {
    const t = rnd(7), ks1 = lv === 1 ? ['A', 'C', 'D', 'Ca', 'Fe'] : Object.keys(NUT);
    if (t === 0) { const k = pick(lv === 1 ? ['A', 'C', 'D', 'Ca'] : SRC_KEYS), r = pick(FOOD.filter(fd => has(fd, k))); return one('Где много ' + NUT[k].l + '?', r.f, sub(FOOD.filter(fd => none(fd, k)), nOpt(lv) - 1).map(fd => fd.f), nWhy(k)); }
    if (t === 1) { const k = pick(ks1); return one('Зачем телу ' + low(NUT[k].n) + '?', cap(NUT[k].w), sub(ks1.filter(x => x !== k && !(k === 'Ca' && x === 'D') && !(k === 'D' && x === 'Ca')), nOpt(lv) - 1).map(x => cap(NUT[x].w)), NUT[k].n + ': ' + NUT[k].w + '.'); }
    if (t === 2) { const k = pick(ks1); return one('Кто это: «' + NUT[k].w + '»?', NUT[k].n, sub(ks1.filter(x => x !== k), nOpt(lv) - 1).map(x => NUT[x].n), NUT[k].n + ': ' + NUT[k].w + '.'); }
    if (t === 3) {
      const k = pick(SRC_KEYS), truth = Math.random() < 0.5, fd = pick(FOOD.filter(x => (truth ? has(x, k) : none(x, k))));
      return tf(fd.f + ' — хороший источник ' + NUT[k].l + '.', truth, (truth ? 'Верно! ' : 'Нет. ') + fWhy(fd));
    }
    if (t === 4) {
      // группы — витамины/минералы; берём только продукты, которые относятся ровно к одной из выбранных групп
      let ks, lists;
      for (let tries = 0; tries < 20; tries++) {
        ks = sub(lv === 1 ? ['A', 'C', 'D'] : SRC_KEYS, lv === 3 ? 3 : 2);
        lists = ks.map(k => FOOD.filter(fd => has(fd, k) && ks.every(x => x === k || none(fd, x))).map(fd => fd.f));
        if (lists.every(l => l.length) && lists.reduce((s, l) => s + l.length, 0) >= (lv === 1 ? 5 : lv === 2 ? 6 : 7)) break;
      }
      if (!lists.every(l => l.length)) { ks = ['A', 'C', 'I']; lists = ks.map(k => FOOD.filter(fd => has(fd, k) && ks.every(x => x === k || none(fd, x))).map(fd => fd.f)); }
      return sortQ('Разложи продукты: чем каждый особенно богат?', ks.map(k => NUT[k].n), lists, lv === 1 ? 5 : lv === 2 ? 6 : 7, ks.map(nWhy).join(' '));
    }
    if (t === 5) { const p = pick(CHAINS); return { type: 'order', q: p.q, items: p.it.slice(), why: p.why }; }
    const k = pick(['A', 'C', 'D', 'Ca', 'Fe']), yes = FOOD.filter(fd => has(fd, k)), n = lv === 1 ? 4 : lv === 2 ? 5 : 6, nIn = 1 + rnd(Math.min(n - 1, yes.length));
    const list = shuf(sub(yes, nIn).concat(sub(FOOD.filter(fd => none(fd, k)), n - nIn)));
    return { type: 'input', q: 'Сколько из этих продуктов — хорошие источники ' + NUT[k].l + ': ' + list.map(fd => low(fd.f)).join(', ') + '?', c: nIn, why: 'Подходят: ' + list.filter(fd => has(fd, k)).map(fd => low(fd.f)).join(', ') + '. ' + NUT[k].n + ' ' + NUT[k].w + '.' };
  };

  // ═════════ 4. Как мы растём: числа о теле, малыш и взрослый
  /* NUM — точные числа (для input/order); все значения разные, чтобы порядок был однозначным */
  const NUM = [
    ['Почек у человека', 2], ['Камер в сердце', 4], ['Главных органов чувств', 5], ['Шейных позвонков', 7], ['Пар рёбер', 12],
    ['Молочных зубов', 20], ['Всего рёбер', 24], ['Костей в кисти вместе с запястьем', 27], ['Постоянных зубов у взрослого вместе с зубами мудрости', 32], ['Костей у взрослого', 206]
  ];
  /* CMP — что больше у малыша, а что у взрослого (только надёжные различия) */
  const CMP = [
    { x: 'Число костей', who: 0, why: 'У новорождённого около 300 косточек, у взрослого — около 206: многие срастаются.' },
    { x: 'Частота пульса в покое', who: 0, why: 'У детей сердце в покое бьётся чаще, чем у взрослых.' },
    { x: 'Частота дыхания в покое', who: 0, why: 'Дети делают больше вдохов в минуту, чем взрослые.' },
    { x: 'Сколько часов нужно спать', who: 0, why: 'Детям нужно спать дольше: школьнику 9–12 часов, взрослому — около 7–9.' },
    { x: 'Доля головы в длине тела', who: 0, why: 'У новорождённого голова — около четверти длины тела, у взрослого — около восьмой части.' },
    { x: 'Доля воды в теле', who: 0, why: 'В теле малыша воды больше всего, с возрастом доля воды немного уменьшается.' },
    { x: 'Сколько сантиметров прибавляется за год', who: 0, why: 'Малыш за первый год вырастает примерно на 25 см, а взрослый уже не растёт.' },
    { x: 'Число зубов', who: 1, why: 'У ребёнка 20 молочных зубов, у взрослого — до 32 постоянных.' },
    { x: 'Литров крови в теле', who: 1, why: 'У взрослого около 5 литров крови, у ребёнка — меньше.' },
    { x: 'Вес мозга', who: 1, why: 'Мозг растёт вместе с ребёнком: у взрослого он весит около 1,3–1,4 кг.' },
    { x: 'Рост', who: 1, why: 'Взрослый выше: мы растём, пока не закроются зоны роста.' }
  ];
  const GTF = [
    ['Больше всего гормона роста выделяется во время глубокого сна', true, 'Поэтому для роста так важно высыпаться.'],
    ['Кости растут в длину в зонах роста у своих концов', true, 'Там хрящ делится и превращается в кость.'],
    ['Зоны роста закрываются примерно к 16–20 годам', true, 'После этого рост вверх останавливается.'],
    ['Гипофиз — крошечная железа у основания мозга, которая выпускает гормон роста', true, 'Он размером примерно с горошину.'],
    ['Малыш за первый год вырастает примерно на 25 см', true, 'Это самый быстрый рост в жизни.'],
    ['Росту помогают сон, еда с белком и кальцием и движение', true, 'Три кита роста: сон, еда, движение.'],
    ['Рост вверх продолжается всю жизнь', false, 'Примерно к 16–20 годам зоны роста закрываются, и рост вверх останавливается.'],
    ['Все дети растут с одинаковой скоростью', false, 'Все растут по-разному и в своё время — это нормально.'],
    ['Больше всего гормона роста выделяется днём, во время игр', false, 'Больше всего — в глубоком сне.'],
    ['У мальчиков скачок роста обычно начинается раньше, чем у девочек', false, 'Обычно наоборот: у девочек — раньше, примерно в 10–12 лет.'],
    ['Таблицы роста у врача показывают одно-единственное правильное число', false, 'Они показывают широкий коридор: нормальным бывает очень разный рост.']
  ];
  /* вопросы-знания о росте: [вопрос, верный, неверные, почему] */
  const GROW_Q = [
    ['Сколько часов сна нужно школьнику?', '9–12 часов', ['4–5 часов', '15–16 часов', '1–2 часа'], 'Во сне тело растёт и отдыхает, а мозг раскладывает по полочкам всё, что удалось узнать за день.'],
    ['Сколько сантиметров в год обычно прибавляет школьник?', 'Около 5–6 см', ['Около 50 см', 'Нисколько', 'Около 1 мм'], 'До скачка роста дети растут спокойно, по нескольку сантиметров в год.'],
    ['Во сколько лет у девочек обычно начинается скачок роста?', 'Примерно в 10–12 лет', ['В 2–3 года', 'В 25 лет', 'Сразу после рождения'], 'У девочек скачок роста обычно начинается раньше, чем у мальчиков.'],
    ['Когда выделяется больше всего гормона роста?', 'Во время глубокого сна', ['Во время обеда', 'Когда смотришь мультики', 'Утром на зарядке'], 'Поэтому, чтобы хорошо расти, важно вовремя ложиться и высыпаться.'],
    ['Где в костях идёт рост в длину?', 'В зонах роста у концов костей', ['В середине кости', 'В суставной смазке', 'В коже над костью'], 'В зонах роста хрящ делится и превращается в кость.'],
    ['Примерно к какому возрасту закрываются зоны роста?', 'К 16–20 годам', ['К 5 годам', 'К 60 годам', 'Никогда не закрываются'], 'После этого рост вверх останавливается.'],
    ['Какая железа выпускает гормон роста?', 'Гипофиз', ['Печень', 'Сердце', 'Желудок'], 'Гипофиз — крошечная железа у основания мозга, размером примерно с горошину.'],
    ['Что больше всего помогает расти?', 'Сон, еда с белком и кальцием и движение', ['Сладости и газировка', 'Сидеть дома у экрана', 'Поздно ложиться'], 'Три кита роста: сон, полезная еда и движение.'],
    ['Как измеряют пульс?', 'Двумя пальцами на запястье, считая удары за минуту', ['Ладонью на лбу', 'Градусником под мышкой', 'Считая вдохи'], 'Толчки крови в артерии на запястье — это и есть пульс.'],
    ['У кого сердце в покое бьётся чаще?', 'У ребёнка', ['У взрослого', 'Одинаково у всех', 'Только у спортсменов'], 'Чем меньше тело, тем чаще бьётся сердце.'],
    ['Почему у малыша больше косточек, чем у взрослого?', 'С возрастом многие косточки срастаются', ['Взрослые теряют кости', 'Малыши едят больше кальция', 'Кости делятся у взрослых'], 'У новорождённого около 300 косточек, у взрослого — около 206.'],
    ['Как врач следит за ростом ребёнка?', 'Сравнивает рост с широким коридором нормы', ['Требует одно точное число', 'Смотрит только на вес мамы', 'Измеряет длину волос'], 'Нормальным бывает очень разный рост — все растут в своём темпе.']
  ];
  U('growth').gen = lv => {
    const t = rnd(7);
    if (t === 0) {
      const m = pick(CMP), opts = lv === 1 ? ['У малыша', 'У взрослого'] : ['У малыша', 'У взрослого', 'Одинаково'];
      return one('«' + m.x + '»: у кого больше — у малыша или у взрослого?', opts[m.who], opts.filter((_, i) => i !== m.who), m.why);
    }
    if (t === 1) { const m = pick(CMP), w = rnd(2); return tf(m.x + ': больше ' + (w ? 'у взрослого, чем у малыша' : 'у малыша, чем у взрослого') + '.', w === m.who, m.why); }
    if (t === 2) {
      const n = lv === 1 ? 5 : lv === 2 ? 6 : 7, a = sub(CMP.filter(m => m.who === 0), 1), b = sub(CMP.filter(m => m.who === 1), 1);
      const items = a.concat(b, sub(CMP.filter(m => m !== a[0] && m !== b[0]), n - 2));
      return { type: 'sort', q: 'Сравни малыша и взрослого: у кого больше?', groups: ['Больше у малыша', 'Больше у взрослого'], items: shuf(items.map(m => [m.x, m.who])), why: items.map(m => m.why).join(' ') };
    }
    if (t === 3) { const ns = sub(NUM, lv === 1 ? 3 : lv === 2 ? 4 : 5).sort((x, y) => x[1] - y[1]); return { type: 'order', q: 'Числа о теле: расставь от меньшего к большему.', items: ns.map(x => x[0]), why: ns.map(x => x[0] + ' — ' + x[1]).join('; ') + '.' }; }
    if (t === 4) { const x = pick(NUM); return { type: 'input', q: x[0] + ' — сколько?', c: x[1], why: x[0] + ': ' + x[1] + '.' }; }
    if (t === 5) { const x = pick(GROW_Q); return one(x[0], x[1], sub(x[2], nOpt(lv) - 1), x[3]); }
    const g = pick(GTF); return tf(g[0] + '.', g[1], (g[1] ? 'Верно! ' : 'Нет. ') + g[2]);
  };
})();
